package main

import (
	"database/sql"
	"encoding/json"
	"net/http"
	"os"

	_ "github.com/mattn/go-sqlite3"
)

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "3000"
	}

	db, _ := sql.Open("sqlite3", ":memory:")
	db.Exec(`CREATE TABLE IF NOT EXISTS _migrations (id INTEGER PRIMARY KEY, name TEXT, applied_at TEXT DEFAULT CURRENT_TIMESTAMP)`)
	db.Exec(`CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL)`)
	db.Exec("INSERT OR IGNORE INTO _migrations (id, name) VALUES (1, 'create_users')")

	http.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(map[string]interface{}{"status": "ok", "migrations": 1})
	})

	http.HandleFunc("/migrate", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		if r.Method == "POST" {
			db.Exec("ALTER TABLE users ADD COLUMN age INTEGER DEFAULT 0")
			db.Exec("INSERT OR IGNORE INTO _migrations (id, name) VALUES (2, 'add_age')")
			json.NewEncoder(w).Encode(map[string]interface{}{"message": "Migration applied", "migration": 2})
		}
	})

	http.HandleFunc("/schema", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		rows, _ := db.Query("PRAGMA table_info(users)")
		var cols []map[string]interface{}
		for rows.Next() {
			var cid, notnull, pk int
			var name, coltype string
			var dflt sql.NullString
			rows.Scan(&cid, &name, &coltype, &notnull, &dflt, &pk)
			cols = append(cols, map[string]interface{}{"cid": cid, "name": name, "type": coltype, "notnull": notnull, "pk": pk})
		}
		json.NewEncoder(w).Encode(cols)
	})

	http.ListenAndServe(":"+port, nil)
}

